/// The gallery's example of `Tooltip`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_shortcut = args.text("shortcut");

        VStack::new((
            Spacer::new().min(40.0),
            HStack::new((
                {
                    let mut it = Tooltip::new(
                        Button::new("Show tip").style(ButtonStyle::Secondary),
                        "It stays out of the way",
                    );
                    if !arg_shortcut.is_empty() {
                        it = it.shortcut(arg_shortcut.clone());
                    }
                    it
                },
                Button::new("Save").style(ButtonStyle::Secondary).tooltip("Save the file"),
                Tooltip::new(Button::new("Open").style(ButtonStyle::Secondary), "Open a file").shortcut("⌘O"),
            ))
            .spacing(8.0),
        ))
    })
}

impl ComponentBook for Tooltip<AnyView> {
    fn book() -> Meta {
        Meta::new("Overlays/Tooltip", render)
            .summary("Short label shown on hover, with an optional key cap.")
            .arg(ArgType::text("shortcut", "").description("Empty leaves it as the component has it."))
            .story("Example", Args::new())
    }
}
